  -- Signals
  SIGNAL init_guard_true_1                : std_logic;
  SIGNAL init_guard_true_2                : std_logic;
  SIGNAL outinit_guard_default            : unsigned(15 DOWNTO 0);  -- ufix16_En15
  SIGNAL S_in_signed                      : signed(36 DOWNTO 0);  -- sfix37_En32
  SIGNAL Converted_test_in                : unsigned(27 DOWNTO 0);  -- ufix28_En27
  SIGNAL Smoothed_test_in                 : std_logic_vector(27 DOWNTO 0);  -- ufix28
  SIGNAL lut_addr_12bit                   : std_logic_vector(15 DOWNTO 0);  -- ufix16
  SIGNAL m                                : std_logic_vector(15 DOWNTO 0);  -- ufix16
  SIGNAL lut_addr_12bit_unsigned          : unsigned(15 DOWNTO 0);  -- uint16
  SIGNAL prelookup_idx                    : unsigned(11 DOWNTO 0);  -- ufix12
  SIGNAL out_rsvd                         : unsigned(15 DOWNTO 0);  -- ufix16_En15
  SIGNAL out_rsvd_1                       : unsigned(15 DOWNTO 0) := to_unsigned(16#0000#, 16);  -- ufix16_En15
  SIGNAL lut_output                       : unsigned(15 DOWNTO 0);  -- ufix16_En15
  SIGNAL K_tmp                            : std_logic_vector(17 DOWNTO 0);  -- ufix18

BEGIN
  -- Post Shift:
  -- lut_output << m
  -- cast to uint18_en10
  -- rSqrt LUT:
  -- parity = 0, return 1/sqrt(address)
  -- parity = 1, return sqrt(2)/sqrt(address)
  -- Leading Zero Count:
  -- LZC = k
  -- x_norm = x_in << k
  -- m = k>>1
  -- r = k & 1
  -- addr = [r, 11address bits]

  u_MOVING_AVG : SEL_toTest_src_MOVING_AVG
    PORT MAP( clk => clk,
              reset => reset,
              In1 => std_logic_vector(Converted_test_in),  -- ufix28_En27
              S_in => Smoothed_test_in  -- ufix28_En27
              );

  u_MATLAB_Function : SEL_toTest_src_MATLAB_Function
    PORT MAP( clk => clk,
              reset => reset,
              x_in => Smoothed_test_in,  -- ufix28_En27
              lut_addr_12bit => lut_addr_12bit,  -- uint16
              m => m  -- uint16
              );

  u_MATLAB_Function1 : SEL_toTest_src_MATLAB_Function1
    PORT MAP( clk => clk,
              reset => reset,
              lut_val_16bit => std_logic_vector(lut_output),  -- ufix16_En15
              m => m,  -- uint16
              K => K_tmp  -- ufix18_En4
              );

  init_guard_true_1 <= '1';

  matching_delays_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        init_guard_true_2 <= '0';
      ELSE 
        init_guard_true_2 <= init_guard_true_1;
      END IF;
    END IF;
  END PROCESS matching_delays_process;


  outinit_guard_default <= to_unsigned(16#0000#, 16);

  S_in_signed <= signed(S_in);

  
  Converted_test_in <= X"FFFFFFF" WHEN ((S_in_signed(36) = '0') AND (S_in_signed(35 DOWNTO 33) /= "000")) OR ((S_in_signed(36) = '0') AND (S_in_signed(32 DOWNTO 5) = X"FFFFFFF")) ELSE
      X"0000000" WHEN S_in_signed(36) = '1' ELSE
      unsigned(S_in_signed(32 DOWNTO 5)) + ('0' & S_in_signed(4));

  lut_addr_12bit_unsigned <= unsigned(lut_addr_12bit);

  
  prelookup_idx <= to_unsigned(16#000#, 12) WHEN lut_addr_12bit_unsigned = to_unsigned(16#0000#, 16) ELSE
      to_unsigned(16#FFF#, 12) WHEN lut_addr_12bit_unsigned >= to_unsigned(16#0FFF#, 16) ELSE
      lut_addr_12bit_unsigned(11 DOWNTO 0);

  out_rsvd <= NORMALIZED_LUT_table_data(to_integer(prelookup_idx));

  PipelineRegister_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      out_rsvd_1 <= out_rsvd;
    END IF;
  END PROCESS PipelineRegister_process;


  
  lut_output <= outinit_guard_default WHEN init_guard_true_2 = '0' ELSE
      out_rsvd_1;

  K <= K_tmp;

END rtl;

